<?php $__env->startSection('content'); ?>
<section class="py-5" style="background-image:url('<?php echo e(asset('foodmart/images/background-pattern.jpg')); ?>');background-size:cover;"><div class="container-fluid"><h1 class="display-5 fw-bold">Cart</h1></div></section>
