ut type="hidden" name="key" value="<?php echo e($item['key']); ?>"></form><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><div class="row justify-content-end"><div class="col-lg-4"><div class="card border-0 shadow-sm rounded-4 p-4 mt-4"><h3>Cart Totals</h3><p>Subtotal: <strong>৳<?php echo e(number_format($totals['subtotal'],0)); ?></strong></p><p>Estimated Delivery: <strong><?php echo e((float) $totals['shipping'] === 0.0 && $totals['subtotal'] > 0 ? 'Free' : '৳'.number_format($totals['shipping'],0)); ?></strong></p><small class="text-muted d-block mb-3">Final delivery charge can change at checkout based on delivery zone.</small><h3>Total: ৳<?php echo e(number_format($totals['grand_total'],0)); ?></h3><a class="btn btn-primary btn-lg w-100" href="<?php echo e(route('checkout.index')); ?>">Proceed to Checkout</a></div></div></div><?php endif; ?></div></section>
